{"sql":"CREATE TABLE IF NOT EXISTS employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary DECIMAL NOT NULL,
  generated_at TIMESTAMP DEFAULT NOW() NOT NULL
);

CREATE OR REPLACE FUNCTION employees.generate_monthly_report(p_report_date DATE) RETURNS INTEGER AS $$
DECLARE
  v_report_id INTEGER;
BEGIN
  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary, generated_at)
  SELECT
    p_report_date,
    (SELECT COUNT(*) FROM employees.department),
    (SELECT COUNT(DISTINCT employee_id) FROM employees.salary WHERE to_date = '9999-01-01'),
    (SELECT AVG(amount) FROM employees.salary WHERE to_date = '9999-01-01'),
    NOW()
  RETURNING report_id INTO v_report_id;

  RETURN v_report_id;
END;
$$ LANGUAGE plpgsql;"}

{"sql":"CREATE TABLE IF NOT EXISTS employees.salary_alerts (
  alert_id SERIAL PRIMARY KEY,
  employee_id BIGINT NOT NULL,
  salary_amount BIGINT NOT NULL,
  alert_date TIMESTAMP DEFAULT NOW() NOT NULL,
  status VARCHAR(10) DEFAULT 'new' NOT NULL
);

CREATE OR REPLACE FUNCTION employees.fn_high_salary_alert() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.amount > 120000 THEN
    INSERT INTO employees.salary_alerts(employee_id, salary_amount, alert_date, status)
    VALUES (NEW.employee_id, NEW.amount, NOW(), 'new');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;
CREATE TRIGGER high_salary_alert
AFTER INSERT ON employees.salary
FOR EACH ROW
EXECUTE FUNCTION employees.fn_high_salary_alert();"}
